    pub(crate) async fn replace_outbound_store_device_exclusion_candidate(
        &self,
        expected: DurableStoreDeviceExclusionOperation,
        replacement: crate::sync::store_outbound::PreparedStoreOperationCommit,
    ) -> Result<DurableStoreDeviceExclusionOperation, DbError> {
        let DurableStoreDeviceExclusionOperation::CandidatePrepared { object, candidate } =
            expected.clone()
        else {
            return Err(DbError::Message(
                "Store-device exclusion has no replaceable activation candidate".to_string(),
            ));
        };
        let next = DurableStoreDeviceExclusionOperation::CandidatePrepared {
            object,
            candidate: replacement,
        };
        next.validate()
            .map_err(store_device_exclusion_journal_error)?;
        if !expected.allows_transition_to(&next) {
            return Err(DbError::Message(
                "replacement Store-device exclusion candidate changes its signed commit"
                    .to_string(),
            ));
        }
        self.call(move |conn| {
            let tx = conn.unchecked_transaction().map_err(DbError::from)?;
            require_store_device_exclusion_transition_on(&tx, &expected, &next)?;
            let next_candidate = next.candidate().expect("validated candidate state");
            match (candidate.merge_head_ref(), next_candidate.merge_head_ref()) {
                (Some(current), Some(replacement)) if current != replacement => {
                    let (winner, prepared) =
                        next_candidate.merge_publication().ok_or_else(|| {
                            DbError::Message(
                                "replacement Merge exclusion candidate has no signed head"
                                    .to_string(),
                            )
                        })?;
                    replace_prepared_merge_head_remote_on(
                        &tx,
                        &current.object,
                        winner,
                        prepared,
                        &candidate.reference,
                    )?;
                }
                (None, None) | (Some(_), Some(_)) => {}
                _ => {
                    return Err(DbError::Message(
                        "replacement exclusion candidate changes Store write policy".to_string(),
                    ));
                }
            }
            update_store_device_exclusion_on(&tx, &expected, &next, true)?;
            tx.commit().map_err(DbError::from)?;
            Ok(next)
        })
        .await
    }

    pub(crate) fn complete_outbound_store_device_exclusion_activation<'a>(
        &'a self,
        expected: DurableStoreDeviceExclusionOperation,
    ) -> Pin<
        Box<dyn Future<Output = Result<DurableStoreDeviceExclusionOperation, DbError>> + Send + 'a>,
    > {
        Box::pin(async move {
            let next = match &expected {
                DurableStoreDeviceExclusionOperation::CandidatePrepared { object, candidate } => {
                    DurableStoreDeviceExclusionOperation::Completed(
                        StoreDeviceExclusionCompletion::Activated {
                            object: object.clone(),
                            candidate: candidate.clone(),
                        },
                    )
                }
                _ => {
                    return Err(DbError::Message(
                        "Store-device exclusion has no activated candidate".to_string(),
                    ));
                }
            };
            let expected = Box::new(expected);
            let next = Box::new(next);
            self.call(move |conn| {
                let tx = conn.unchecked_transaction().map_err(DbError::from)?;
                require_store_device_exclusion_transition_on(
                    &tx,
                    expected.as_ref(),
                    next.as_ref(),
                )?;
                let candidate = expected
                    .candidate()
                    .expect("candidate-prepared exclusion has a candidate");
                let stream = match &candidate.reference.coord {
                    StoreCommitCoord::MergeConcurrent { stream_id, .. } => stream_id.to_string(),
                    StoreCommitCoord::Serial { .. } => SERIAL_STREAM_ID.to_string(),
                };
                if Self::materialized_commit_ref_on(
                    &tx,
                    &stream,
                    candidate.reference.coord.sequence(),
                )? != Some(candidate.reference.clone())
                {
                    return Err(DbError::Message(
                    "Store-device exclusion completion is not materialized at its exact position"
                        .to_string(),
                ));
                }
                update_store_device_exclusion_on(&tx, expected.as_ref(), next.as_ref(), false)?;
                tx.commit().map_err(DbError::from)?;
                Ok(*next)
            })
            .await
        })
    }

    pub(crate) async fn complete_outbound_store_device_exclusion_slot_loss(
        &self,
        expected: DurableStoreDeviceExclusionOperation,
        winner: crate::sync::store_device_exclusion::DurableStoreDeviceExclusionObject,
    ) -> Result<DurableStoreDeviceExclusionOperation, DbError> {
        let next = DurableStoreDeviceExclusionOperation::Completed(
            StoreDeviceExclusionCompletion::OutcomeSlotOccupied {
                intended: expected.object().clone(),
                winner,
            },
        );
        next.validate()
            .map_err(store_device_exclusion_journal_error)?;
        let remotes = expected
            .remote_objects()
            .map_err(store_device_exclusion_journal_error)?;
        self.call(move |conn| {
            let tx = conn.unchecked_transaction().map_err(DbError::from)?;
            require_store_device_exclusion_transition_on(&tx, &expected, &next)?;
            for remote in &remotes {
                let object_id = remote.object_id();
                let current = load_remote_object_on(&tx, object_id)?;
                let unuploaded = matches!(
                    &current,
                    RemoteObjectRecord::CandidateCommit(record)
                        if matches!(record.state, crate::sync::remote_object::CandidateCommitState::Prepared)
                ) || matches!(
                    &current,
                    RemoteObjectRecord::RetainedAuthority(record)
                        if matches!(
                            record.state,
                            crate::sync::remote_object::RetainedAuthorityObjectState::Prepared { .. }
                        )
                );
                if current != *remote || !unuploaded {
                    return Err(DbError::Message(format!(
                        "outcome-slot loss cannot discard uploaded exclusion object {object_id}"
                    )));
                }
                if tx
                    .execute(
                        "DELETE FROM remote_objects WHERE object_id = ?1",
                        [object_id.to_string()],
                    )
                    .map_err(DbError::from)?
                    != 1
                {
                    return Err(DbError::Message(format!(
                        "unuploaded exclusion object {object_id} disappeared during slot resolution"
                    )));
                }
            }
            update_store_device_exclusion_on(&tx, &expected, &next, false)?;
            tx.commit().map_err(DbError::from)?;
            Ok(next)
        })
        .await
    }

    pub(crate) async fn begin_outbound_store_device_exclusion_nonactivation(
        &self,
        expected: DurableStoreDeviceExclusionOperation,
        nonactivation: crate::sync::remote_object::VerifiedCandidateNonactivation,
    ) -> Result<DurableStoreDeviceExclusionOperation, DbError> {
        let candidate = expected.candidate().cloned().ok_or_else(|| {
            DbError::Message("Store-device exclusion has no losing candidate".to_string())
        })?;
        if nonactivation
            .candidate_reference()
            .map_err(|error| DbError::Message(error.to_string()))?
            != candidate.reference
        {
            return Err(DbError::Message(
                "verified nonactivation names another Store-device exclusion candidate".to_string(),
            ));
        }
        let nonactivation = nonactivation.into_durable();
        let (next, nonactivation) = expected
            .begin_nonactivation(nonactivation)
            .map_err(store_device_exclusion_journal_error)?;
        if nonactivation.candidate().canonical_signed_bytes != candidate.commit.to_bytes() {
            return Err(DbError::Message(
                "verified nonactivation bytes differ from the Store-device exclusion candidate"
                    .to_string(),
            ));
        }
        self.call(move |conn| {
            let tx = conn.unchecked_transaction().map_err(DbError::from)?;
            require_store_device_exclusion_transition_on(&tx, &expected, &next)?;
            let authority_id = remote_object_id(expected.object().object());
            if begin_remote_candidate_nonactivation_on(&tx, authority_id, nonactivation.clone())?
                .is_some()
            {
                return Err(DbError::Message(
                    "uploaded exclusion authority became a deletion target".to_string(),
                ));
            }
            if let Some(head) = candidate.merge_head_ref() {
                if begin_remote_candidate_nonactivation_on(
                    &tx,
                    remote_object_id(&head.object),
                    nonactivation.clone(),
                )?
                .is_some()
                {
                    return Err(DbError::Message(
                        "Store-device exclusion activation head became a deletion target"
                            .to_string(),
                    ));
                }
            }
            if begin_remote_candidate_nonactivation_on(
                &tx,
                remote_object_id(&candidate.reference.object),
                nonactivation,
            )?
            .is_none()
            {
                return Err(DbError::Message(
                    "losing Store-device exclusion commit has no deletion target".to_string(),
                ));
            }
            update_store_device_exclusion_on(&tx, &expected, &next, true)?;
            tx.commit().map_err(DbError::from)?;
            Ok(next)
        })
        .await
    }

    pub(crate) async fn begin_outbound_store_device_exclusion_replacement(
        &self,
        expected: DurableStoreDeviceExclusionOperation,
        replacement: crate::sync::store_outbound::PreparedStoreOperationCommit,
        nonactivation: crate::sync::remote_object::VerifiedCandidateNonactivation,
    ) -> Result<DurableStoreDeviceExclusionOperation, DbError> {
        let expected_candidate = expected.candidate().cloned().ok_or_else(|| {
            DbError::Message("Store-device exclusion has no losing candidate".to_string())
        })?;
        if nonactivation
            .candidate_reference()
            .map_err(|error| DbError::Message(error.to_string()))?
            != expected_candidate.reference
        {
            return Err(DbError::Message(
                "verified nonactivation names another Store-device exclusion candidate".to_string(),
            ));
        }
        let nonactivation = nonactivation.into_durable();
        let (next, nonactivation) = expected
            .begin_replacement(replacement, nonactivation)
            .map_err(store_device_exclusion_journal_error)?;
        if nonactivation.candidate().canonical_signed_bytes != expected_candidate.commit.to_bytes()
        {
            return Err(DbError::Message(
                "verified nonactivation bytes differ from the Store-device exclusion candidate"
                    .to_string(),
            ));
        }
        let DurableStoreDeviceExclusionOperation::ReplacingCandidate {
            candidate, losing, ..
        } = &next
        else {
            unreachable!("begin_replacement returns replacement state")
        };
        let replacement_candidate = candidate.clone();
        let losing_candidate = losing.candidate.clone();
        let authority_id = remote_object_id(expected.object().object());
        let replacement_remotes = DurableStoreDeviceExclusionOperation::CandidatePrepared {
            object: expected.object().clone(),
            candidate: replacement_candidate.clone(),
        }
        .remote_objects()
        .map_err(store_device_exclusion_journal_error)?;
        self.call(move |conn| {
            let tx = conn.unchecked_transaction().map_err(DbError::from)?;
            require_store_device_exclusion_transition_on(&tx, &expected, &next)?;
            for remote in replacement_remotes
                .iter()
                .filter(|remote| remote.object_id() != authority_id)
            {
                persist_exact_remote_object_on(
                    &tx,
                    remote,
                    "replacement Store-device exclusion candidate object",
                )?;
            }
            let mut authority = load_remote_object_on(&tx, authority_id)?;
            authority
                .add_retained_authority_candidate(replacement_candidate.reference.clone())
                .map_err(|error| {
                    DbError::Message(format!(
                        "attach replacement exclusion candidate authority: {error}"
                    ))
                })?;
            update_remote_object_on(&tx, authority_id, &authority)?;
            if begin_remote_candidate_nonactivation_on(&tx, authority_id, nonactivation.clone())?
                .is_some()
            {
                return Err(DbError::Message(
                    "reusable exclusion outcome became a deletion target".to_string(),
                ));
            }
            if let Some(head) = losing_candidate.merge_head_ref() {
                if begin_remote_candidate_nonactivation_on(
                    &tx,
                    remote_object_id(&head.object),
                    nonactivation.clone(),
                )?
                .is_some()
                {
                    return Err(DbError::Message(
                        "losing exclusion activation head became a deletion target".to_string(),
                    ));
                }
            }
            if begin_remote_candidate_nonactivation_on(
                &tx,
                remote_object_id(&losing_candidate.reference.object),
                nonactivation,
            )?
            .is_none()
            {
                return Err(DbError::Message(
                    "losing exclusion candidate has no exact deletion target".to_string(),
                ));
            }
            update_store_device_exclusion_on(&tx, &expected, &next, true)?;
            tx.commit().map_err(DbError::from)?;
            Ok(next)
        })
        .await
    }

    pub(crate) async fn nonactivating_store_device_exclusion_cleanup_targets(
        &self,
        expected: DurableStoreDeviceExclusionOperation,
    ) -> Result<Vec<CandidateCleanupObject>, DbError> {
        self.call(move |conn| {
            let current = load_store_device_exclusion_on(conn, expected.operation_id())?
                .ok_or_else(|| {
                    DbError::Message("Store-device exclusion journal is absent".to_string())
                })?;
            if current != expected {
                return Err(DbError::Message(
                    "Store-device exclusion is not awaiting candidate cleanup".to_string(),
                ));
            }
            let candidate = match &current {
                DurableStoreDeviceExclusionOperation::CandidateNonactivating {
                    candidate, ..
                } => candidate,
                DurableStoreDeviceExclusionOperation::ReplacingCandidate { losing, .. } => {
                    &losing.candidate
                }
                _ => {
                    return Err(DbError::Message(
                        "Store-device exclusion is not awaiting candidate cleanup".to_string(),
                    ));
                }
            };
            let commit =
                load_remote_object_on(conn, remote_object_id(&candidate.reference.object))?;
            if let Some(object) = commit.cleanup_target() {
                Ok(vec![CandidateCleanupObject {
                    object: object.clone(),
                }])
            } else if commit
                .candidate_cleanup_complete(&candidate.reference)
                .map_err(|error| DbError::Message(error.to_string()))?
            {
                Ok(Vec::new())
            } else {
                Err(DbError::Message(
                    "losing Store-device exclusion commit is not awaiting deletion".to_string(),
                ))
            }
        })
        .await
    }

    pub(crate) async fn complete_store_device_exclusion_replacement_cleanup(
        &self,
        expected: DurableStoreDeviceExclusionOperation,
    ) -> Result<DurableStoreDeviceExclusionOperation, DbError> {
        let DurableStoreDeviceExclusionOperation::ReplacingCandidate {
            object,
            candidate,
            losing,
        } = expected.clone()
        else {
            return Err(DbError::Message(
                "Store-device exclusion has no replacement cleanup".to_string(),
            ));
        };
        let next = DurableStoreDeviceExclusionOperation::CandidatePrepared {
            object: object.clone(),
            candidate,
        };
        next.validate()
            .map_err(store_device_exclusion_journal_error)?;
        self.call(move |conn| {
            let tx = conn.unchecked_transaction().map_err(DbError::from)?;
            require_store_device_exclusion_transition_on(&tx, &expected, &next)?;
            let commit_id = remote_object_id(&losing.candidate.reference.object);
            let commit = load_remote_object_on(&tx, commit_id)?;
            if !commit
                .candidate_cleanup_complete(&losing.candidate.reference)
                .map_err(|error| DbError::Message(error.to_string()))?
                || commit
                    .candidate_nonactivation_proof(&losing.candidate.reference)
                    .map_err(|error| DbError::Message(error.to_string()))?
                    != Some(&losing.proof)
            {
                return Err(DbError::Message(
                    "replaced exclusion commit lacks complete nonactivation evidence".to_string(),
                ));
            }
            let authority = load_remote_object_on(&tx, remote_object_id(object.object()))?;
            if !authority
                .candidate_cleanup_complete(&losing.candidate.reference)
                .map_err(|error| DbError::Message(error.to_string()))?
                || authority
                    .candidate_nonactivation_proof(&losing.candidate.reference)
                    .map_err(|error| DbError::Message(error.to_string()))?
                    != Some(&losing.proof)
            {
                return Err(DbError::Message(
                    "reusable exclusion outcome lacks its former candidate proof".to_string(),
                ));
            }
            let mut removable = vec![commit_id];
            if let Some(head) = losing.candidate.merge_head_ref() {
                let head_id = remote_object_id(&head.object);
                let remote = load_remote_object_on(&tx, head_id)?;
                if !remote
                    .candidate_cleanup_complete(&losing.candidate.reference)
                    .map_err(|error| DbError::Message(error.to_string()))?
                    || remote
                        .candidate_nonactivation_proof(&losing.candidate.reference)
                        .map_err(|error| DbError::Message(error.to_string()))?
                        != Some(&losing.proof)
                {
                    return Err(DbError::Message(
                        "replaced exclusion head lacks complete nonactivation evidence".to_string(),
                    ));
                }
                removable.push(head_id);
            }
            for object_id in removable {
                if tx
                    .execute(
                        "DELETE FROM remote_objects WHERE object_id = ?1",
                        [object_id.to_string()],
                    )
                    .map_err(DbError::from)?
                    != 1
                {
                    return Err(DbError::Message(format!(
                        "replaced exclusion object {object_id} disappeared during cleanup"
                    )));
                }
            }
            update_store_device_exclusion_on(&tx, &expected, &next, true)?;
            tx.commit().map_err(DbError::from)?;
            Ok(next)
        })
        .await
    }

    pub(crate) async fn complete_nonactivating_store_device_exclusion(
        &self,
        expected: DurableStoreDeviceExclusionOperation,
    ) -> Result<DurableStoreDeviceExclusionOperation, DbError> {
        let DurableStoreDeviceExclusionOperation::CandidateNonactivating {
            object,
            candidate,
            proof,
        } = expected.clone()
        else {
            return Err(DbError::Message(
                "Store-device exclusion is not nonactivating".to_string(),
            ));
        };
        let next = DurableStoreDeviceExclusionOperation::Completed(
            StoreDeviceExclusionCompletion::CandidateNonactivated {
                object: object.clone(),
                candidate: candidate.clone(),
                proof: proof.clone(),
            },
        );
        next.validate()
            .map_err(store_device_exclusion_journal_error)?;
        self.call(move |conn| {
            let tx = conn.unchecked_transaction().map_err(DbError::from)?;
            require_store_device_exclusion_transition_on(&tx, &expected, &next)?;
            let commit_id = remote_object_id(&candidate.reference.object);
            let commit = load_remote_object_on(&tx, commit_id)?;
            if !commit
                .candidate_cleanup_complete(&candidate.reference)
                .map_err(|error| DbError::Message(error.to_string()))?
                || commit
                    .candidate_nonactivation_proof(&candidate.reference)
                    .map_err(|error| DbError::Message(error.to_string()))?
                    != Some(&proof)
            {
                return Err(DbError::Message(
                    "losing exclusion commit lacks complete exact nonactivation evidence"
                        .to_string(),
                ));
            }
            let inert = load_protocol_inert_object_on(&tx, remote_object_id(object.object()))?;
            if inert
                .candidate_nonactivation_proof(&candidate.reference)
                .map_err(|error| DbError::Message(error.to_string()))?
                != Some(&proof)
            {
                return Err(DbError::Message(
                    "protocol-inert exclusion object lacks its candidate proof".to_string(),
                ));
            }
            let mut removable = vec![commit_id];
            if let Some(head) = candidate.merge_head_ref() {
                let head_id = remote_object_id(&head.object);
                let head_remote = load_remote_object_on(&tx, head_id)?;
                if !head_remote
                    .candidate_cleanup_complete(&candidate.reference)
                    .map_err(|error| DbError::Message(error.to_string()))?
                    || head_remote
                        .candidate_nonactivation_proof(&candidate.reference)
                        .map_err(|error| DbError::Message(error.to_string()))?
                        != Some(&proof)
                {
                    return Err(DbError::Message(
                        "losing exclusion head lacks complete nonactivation evidence".to_string(),
                    ));
                }
                removable.push(head_id);
            }
            for object_id in removable {
                if tx
                    .execute(
                        "DELETE FROM remote_objects WHERE object_id = ?1",
                        [object_id.to_string()],
                    )
                    .map_err(DbError::from)?
                    != 1
                {
                    return Err(DbError::Message(format!(
                        "nonactivating exclusion object {object_id} disappeared during completion"
                    )));
                }
            }
            update_store_device_exclusion_on(&tx, &expected, &next, false)?;
            tx.commit().map_err(DbError::from)?;
            Ok(next)
        })
        .await
    }

    pub(crate) async fn outbound_membership_mutation(
        &self,
    ) -> Result<Option<DurableMembershipMutation>, DbError> {
        self.call(|conn| {
            conn.query_row(
                "SELECT intent_hash, plan_bytes, progress_bytes \
                 FROM outbound_membership_mutation WHERE singleton = 1",
                [],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, Vec<u8>>(1)?,
                        row.get::<_, Vec<u8>>(2)?,
                    ))
                },
            )
            .optional()
            .map_err(DbError::from)?
            .map(|(hash, plan_bytes, progress_bytes)| {
                let intent_hash: ObjectHash = hash.parse().map_err(|error| {
                    DbError::Message(format!("membership intent hash: {error}"))
                })?;
                if ObjectHash::digest(&plan_bytes) != intent_hash {
                    return Err(DbError::Message(
                        "membership intent hash differs from its exact plan bytes".to_string(),
                    ));
                }
                Ok(DurableMembershipMutation {
                    intent_hash,
                    plan_bytes,
                    progress_bytes,
                })
            })
            .transpose()
        })
        .await
    }

    pub(crate) async fn select_membership_author_stream(
        &self,
        author_pubkey: &str,
        author_owner_grant: &crate::sync::membership::MembershipGrantId,
        reusable: std::collections::BTreeSet<crate::sync::membership::AuthorStreamId>,
    ) -> Result<crate::sync::membership::AuthorStreamId, DbError> {
        self.select_causal_author_stream(
            format!("membership_author_stream/{author_pubkey}/{author_owner_grant}"),
            reusable,
        )
        .await
    }

    pub(crate) async fn registered_stream_activation(
        &self,
        activation_id: StreamActivationId,
    ) -> Result<Option<crate::sync::store_commit::RegisteredStreamActivation>, DbError> {
        self.call(move |conn| {
            load_registered_stream_activation_on(conn, &activation_id.as_hash().to_string())
        })
        .await
    }

    pub(crate) async fn select_causal_author_stream(
        &self,
        key: String,
        reusable: std::collections::BTreeSet<crate::sync::membership::AuthorStreamId>,
    ) -> Result<crate::sync::membership::AuthorStreamId, DbError> {
        let candidate = crate::sync::membership::AuthorStreamId::from_digest(ObjectHash::digest(
            self.id_provider().new_id().as_bytes(),
        ));
        self.call(move |conn| {
            let existing = conn
                .query_row(
                    "SELECT value FROM protocol_state WHERE key = ?1",
                    [&key],
                    |row| row.get::<_, String>(0),
                )
                .optional()
                .map_err(DbError::from)?
                .map(|value| {
                    value.parse().map_err(|error| {
                        DbError::Message(format!(
                            "membership author stream state is malformed: {error}"
                        ))
                    })
                })
                .transpose()?;
            if let Some(existing) = existing {
                if reusable.contains(&existing) {
                    return Ok(existing);
                }
            }
            let selected = reusable.iter().next_back().copied().unwrap_or(candidate);
            conn.execute(
                "INSERT INTO protocol_state (key, value) VALUES (?1, ?2) \
                 ON CONFLICT(key) DO UPDATE SET value = excluded.value",
                rusqlite::params![key, selected.to_string()],
            )
            .map_err(DbError::from)?;
            Ok(selected)
        })
        .await
    }

    pub(crate) async fn stage_membership_mutation(
        &self,
        plan_bytes: Vec<u8>,
        progress_bytes: Vec<u8>,
    ) -> Result<ObjectHash, DbError> {
        self.call(move |conn| {
            let intent_hash = ObjectHash::digest(&plan_bytes);
            let existing = conn
                .query_row(
                    "SELECT intent_hash, plan_bytes FROM outbound_membership_mutation \
                     WHERE singleton = 1",
                    [],
                    |row| Ok((row.get::<_, String>(0)?, row.get::<_, Vec<u8>>(1)?)),
                )
                .optional()
                .map_err(DbError::from)?;
            if let Some((existing_hash, existing_plan)) = existing {
                if existing_hash == intent_hash.to_string() && existing_plan == plan_bytes {
                    return Ok(intent_hash);
                }
                return Err(DbError::Message(
                    "a different membership mutation is already pending".to_string(),
                ));
            }
            conn.execute(
                "INSERT INTO outbound_membership_mutation \
                 (singleton, intent_hash, plan_bytes, progress_bytes) \
                 VALUES (1, ?1, ?2, ?3)",
                rusqlite::params![intent_hash.to_string(), plan_bytes, progress_bytes],
            )
            .map_err(DbError::from)?;
            Ok(intent_hash)
        })
        .await
    }

    pub(crate) async fn stage_serial_membership_mutation(
        &self,
        plan_bytes: Vec<u8>,
        progress_bytes: Vec<u8>,
        remote_objects: Vec<RemoteObjectRecord>,
    ) -> Result<ObjectHash, DbError> {
        self.call(move |conn| {
            let intent_hash = ObjectHash::digest(&plan_bytes);
            let tx = conn.unchecked_transaction().map_err(DbError::from)?;
            let existing = tx
                .query_row(
                    "SELECT intent_hash, plan_bytes FROM outbound_membership_mutation \
                     WHERE singleton = 1",
                    [],
                    |row| Ok((row.get::<_, String>(0)?, row.get::<_, Vec<u8>>(1)?)),
                )
                .optional()
                .map_err(DbError::from)?;
            if let Some((existing_hash, existing_plan)) = existing {
                if existing_hash != intent_hash.to_string() || existing_plan != plan_bytes {
                    return Err(DbError::Message(
                        "a different membership mutation is already pending".to_string(),
                    ));
                }
                for remote in &remote_objects {
                    let stored = load_remote_object_on(&tx, remote.object_id())?;
                    if stored != *remote {
                        return Err(DbError::Message(
                            "persisted Serial membership ownership differs from its durable plan"
                                .to_string(),
                        ));
                    }
                }
                tx.commit().map_err(DbError::from)?;
                return Ok(intent_hash);
            }
            if remote_objects.is_empty() {
                return Err(DbError::Message(
                    "Serial membership mutation has no remote ownership graph".to_string(),
                ));
            }
            let mut object_ids = BTreeSet::new();
            for remote in &remote_objects {
                if !object_ids.insert(remote.object_id()) {
                    return Err(DbError::Message(
                        "Serial membership mutation repeats a remote object".to_string(),
                    ));
                }
                persist_exact_remote_object_on(&tx, remote, "Serial membership candidate object")?;
            }
            tx.execute(
                "INSERT INTO outbound_membership_mutation \
                 (singleton, intent_hash, plan_bytes, progress_bytes) \
                 VALUES (1, ?1, ?2, ?3)",
                rusqlite::params![intent_hash.to_string(), plan_bytes, progress_bytes],
            )
            .map_err(DbError::from)?;
            tx.commit().map_err(DbError::from)?;
            Ok(intent_hash)
        })
        .await
    }

    pub(crate) async fn update_membership_mutation_progress(
        &self,
        intent_hash: ObjectHash,
        progress_bytes: Vec<u8>,
    ) -> Result<(), DbError> {
        self.call(move |conn| {
            let updated = conn
                .execute(
                    "UPDATE outbound_membership_mutation SET progress_bytes = ?1 \
                     WHERE singleton = 1 AND intent_hash = ?2",
                    rusqlite::params![progress_bytes, intent_hash.to_string()],
                )
                .map_err(DbError::from)?;
            if updated != 1 {
                return Err(DbError::Message(
                    "membership mutation ownership row is absent or changed".to_string(),
                ));
            }
            Ok(())
        })
        .await
    }

    pub(crate) async fn replace_serial_membership_candidate(
        &self,
        intent_hash: ObjectHash,
        plan_bytes: Vec<u8>,
    ) -> Result<ObjectHash, DbError> {
        self.call(move |conn| {
            let replacement_hash = ObjectHash::digest(&plan_bytes);
            let updated = conn
                .execute(
                    "UPDATE outbound_membership_mutation \
                     SET intent_hash = ?1, plan_bytes = ?2 \
                     WHERE singleton = 1 AND intent_hash = ?3",
                    rusqlite::params![
                        replacement_hash.to_string(),
                        plan_bytes,
                        intent_hash.to_string()
                    ],
                )
                .map_err(DbError::from)?;
            if updated != 1 {
                return Err(DbError::Message(
                    "Serial membership mutation changed before candidate receipt adoption"
                        .to_string(),
                ));
            }
            Ok(replacement_hash)
        })
        .await
    }

    pub(crate) async fn begin_serial_membership_candidate_nonactivation(
        &self,
        intent_hash: ObjectHash,
        candidate: StoreBatchCommitRef,
        wrapped_keys: Vec<ExactObjectRef>,
        progress_bytes: Vec<u8>,
        nonactivation: crate::sync::remote_object::VerifiedCandidateNonactivation,
    ) -> Result<CandidateCleanupObject, DbError> {
        if nonactivation
            .candidate_reference()
            .map_err(|error| DbError::Message(error.to_string()))?
            != candidate
        {
            return Err(DbError::Message(
                "verified nonactivation names another Serial membership candidate".to_string(),
            ));
        }
        let nonactivation = nonactivation.into_durable();
        self.call(move |conn| {
            let tx = conn.unchecked_transaction().map_err(DbError::from)?;
            let exists: bool = tx
                .query_row(
                    "SELECT EXISTS(
                         SELECT 1 FROM outbound_membership_mutation
                         WHERE singleton = 1 AND intent_hash = ?1
                     )",
                    [intent_hash.to_string()],
                    |row| row.get(0),
                )
                .map_err(DbError::from)?;
            if !exists {
                return Err(DbError::Message(
                    "Serial membership mutation changed before nonactivation".to_string(),
                ));
            }
            let mut unique = BTreeSet::new();
            for object in &wrapped_keys {
                let object_id = remote_object_id(object);
                if !unique.insert(object_id) {
                    return Err(DbError::Message(
                        "Serial membership nonactivation repeats a wrapped key".to_string(),
                    ));
                }
                if begin_remote_candidate_nonactivation_on(&tx, object_id, nonactivation.clone())?
                    .is_some()
                {
                    return Err(DbError::Message(
                        "losing Serial membership wrap became a deletion target".to_string(),
                    ));
                }
            }
            let commit_target = begin_remote_candidate_nonactivation_on(
                &tx,
                remote_object_id(&candidate.object),
                nonactivation,
            )?
            .ok_or_else(|| {
                DbError::Message(
                    "losing Serial membership commit has no exact deletion target".to_string(),
                )
            })?;
            if commit_target != candidate.object {
                return Err(DbError::Message(
                    "Serial membership cleanup target differs from its candidate commit"
                        .to_string(),
                ));
            }
            let updated = tx
                .execute(
                    "UPDATE outbound_membership_mutation SET progress_bytes = ?1 \
                     WHERE singleton = 1 AND intent_hash = ?2",
                    rusqlite::params![progress_bytes, intent_hash.to_string()],
                )
                .map_err(DbError::from)?;
            if updated != 1 {
                return Err(DbError::Message(
                    "Serial membership mutation changed during nonactivation".to_string(),
                ));
            }
            tx.commit().map_err(DbError::from)?;
            Ok(CandidateCleanupObject {
                object: commit_target,
            })
        })
        .await
    }

    pub(crate) async fn complete_nonactivating_serial_membership_mutation(
        &self,
        intent_hash: ObjectHash,
        candidate: StoreBatchCommitRef,
        wrapped_keys: Vec<ExactObjectRef>,
    ) -> Result<(), DbError> {
        self.call(move |conn| {
            let tx = conn.unchecked_transaction().map_err(DbError::from)?;
            let commit_id = remote_object_id(&candidate.object);
            let commit = load_remote_object_on(&tx, commit_id)?;
            if !commit
                .candidate_cleanup_complete(&candidate)
                .map_err(|error| DbError::Message(error.to_string()))?
            {
                return Err(DbError::Message(
                    "losing Serial membership commit cleanup is incomplete".to_string(),
                ));
            }
            for object in wrapped_keys {
                let object_id = remote_object_id(&object);
                let inert = load_protocol_inert_object_on(&tx, object_id)?;
                if inert.object_id() != object_id {
                    return Err(DbError::Message(
                        "protocol-inert Serial membership wrap changed exact identity".to_string(),
                    ));
                }
            }
            if tx
                .execute(
                    "DELETE FROM remote_objects WHERE object_id = ?1",
                    [commit_id.to_string()],
                )
                .map_err(DbError::from)?
                != 1
            {
                return Err(DbError::Message(
                    "losing Serial membership commit disappeared during removal".to_string(),
                ));
            }
            if tx
                .execute(
                    "DELETE FROM outbound_membership_mutation \
                     WHERE singleton = 1 AND intent_hash = ?1",
                    [intent_hash.to_string()],
                )
                .map_err(DbError::from)?
                != 1
            {
                return Err(DbError::Message(
                    "Serial membership mutation changed during completion".to_string(),
                ));
            }
            tx.commit().map_err(DbError::from)
        })
        .await
    }

    pub(crate) async fn complete_activated_serial_membership_mutation(
        &self,
        intent_hash: ObjectHash,
        candidate: StoreBatchCommitRef,
        wrapped_keys: Vec<ExactObjectRef>,
    ) -> Result<(), DbError> {
        self.call(move |conn| {
            let tx = conn.unchecked_transaction().map_err(DbError::from)?;
            let mut objects = vec![candidate.object.clone()];
            objects.extend(wrapped_keys);
            let mut unique = BTreeSet::new();
            for object in objects {
                let object_id = remote_object_id(&object);
                if !unique.insert(object_id) {
                    return Err(DbError::Message(
                        "activated Serial membership graph repeats an exact object".to_string(),
                    ));
                }
                let remote = load_remote_object_on(&tx, object_id)?;
                let activated = remote.clone().into_activated(&candidate).map_err(|error| {
                    DbError::Message(format!(
                        "validate activated Serial membership object {object_id}: {error}"
                    ))
                })?;
                if activated != remote {
                    return Err(DbError::Message(format!(
                        "Serial membership object {object_id} still has pending candidate ownership"
                    )));
                }
            }
            if tx
                .execute(
                    "DELETE FROM outbound_membership_mutation \
                     WHERE singleton = 1 AND intent_hash = ?1",
                    [intent_hash.to_string()],
                )
                .map_err(DbError::from)?
                != 1
            {
                return Err(DbError::Message(
                    "Serial membership mutation changed during activated completion".to_string(),
                ));
            }
            tx.commit().map_err(DbError::from)
        })
        .await
    }

    pub(crate) async fn complete_membership_mutation(
        &self,
        intent_hash: ObjectHash,
    ) -> Result<(), DbError> {
        self.call(move |conn| {
            let deleted = conn
                .execute(
                    "DELETE FROM outbound_membership_mutation \
                     WHERE singleton = 1 AND intent_hash = ?1",
                    [intent_hash.to_string()],
                )
                .map_err(DbError::from)?;
            if deleted != 1 {
                return Err(DbError::Message(
                    "membership mutation ownership row is absent or changed".to_string(),
                ));
            }
            Ok(())
        })
        .await
    }

    pub(crate) async fn outbound_snapshot_publication(
        &self,
    ) -> Result<Option<DurableSnapshotPublication>, DbError> {
        let pending = self.call(load_outbound_store_snapshot_on).await?;
        if let Some(pending) = &pending {
            for blob in &pending.blobs {
                if let Some(spool_path) = &blob.spool_path {
                    crate::local_blob::verify_exact_file(blob.remote.object(), spool_path)
                        .await
                        .map_err(|error| {
                            DbError::Message(format!("prepared snapshot blob spool: {error}"))
                        })?;
                }
            }
        }
        Ok(pending)
    }

    pub(crate) async fn stage_snapshot_publication(
        &self,
        meta: SnapshotMeta,
        meta_prepared: PreparedExactObject,
        image_bytes: Vec<u8>,
        image_prepared: PreparedExactObject,
        blobs: Vec<PreparedSnapshotBlob>,
    ) -> Result<StoreSnapshotRef, DbError> {
        let synced_tables = self.synced_tables().to_vec();
        let gates = self.gates();
        self.call(move |conn| {
            let tx = conn.unchecked_transaction().map_err(DbError::from)?;
            let (root, registration_ref, registration) = local_store_authority_on(&tx)?;
            if meta.author_registration != registration_ref {
                return Err(DbError::Message(
                    "staged Store snapshot author differs from local activation".to_string(),
                ));
            }
            if meta.image.object != *image_prepared.reference()
                || ObjectHash::digest(&image_bytes) != meta.image.image_hash
                || meta.image.object.slot().logical_key()
                    != format!(
                        "{}.db",
                        snapshot_image_semantic_prefix(
                            &registration.device_id.to_string(),
                            meta.image.image_hash,
                        )
                    )
            {
                return Err(DbError::Message(
                    "staged Store snapshot image differs from its exact reference".to_string(),
                ));
            }
            let reference = StoreSnapshotRef {
                sequence: meta.sequence,
                snapshot_hash: meta.snapshot_hash(),
                object: meta_prepared.reference().clone(),
            };
            let verified = SnapshotMeta::parse_at(
                &meta.to_bytes(),
                root.store_root_hash,
                &reference,
                &registration,
            )
            .map_err(|error| {
                DbError::Message(format!("verify staged Store snapshot metadata: {error}"))
            })?;
            if verified != meta {
                return Err(DbError::Message(
                    "staged Store snapshot changed during exact verification".to_string(),
                ));
            }
            let previous = load_published_store_snapshot_on(&tx)?;
            let (expected_sequence, expected_predecessor, expected_slot) = match &previous {
                Some(previous) => (
                    previous.reference.sequence.checked_add(1).ok_or_else(|| {
                        DbError::Message("Store snapshot sequence overflow".to_string())
                    })?,
                    Some(previous.reference.clone()),
                    previous.successor_slot.clone(),
                ),
                None => (1, None, store_snapshot_first_slot(&registration)?.clone()),
            };
            if meta.sequence != expected_sequence
                || meta.predecessor != expected_predecessor
                || meta_prepared.reference().slot() != &expected_slot
                || meta.successor.predecessor
                    != previous
                        .as_ref()
                        .map(|value| value.reference.object.clone())
            {
                return Err(DbError::Message(
                    "Store snapshot does not extend the exact local stream".to_string(),
                ));
            }
            let next_sequence = meta
                .sequence
                .checked_add(1)
                .ok_or_else(|| DbError::Message("Store snapshot sequence overflow".to_string()))?;
            if meta.successor.activation
                != registration
                    .store_snapshot_activation(&registration_ref)
                    .map_err(|error| DbError::Message(error.to_string()))?
                    .activation_id()
                || meta.successor.next_slot.logical_key()
                    != format!(
                        "{}.json",
                        snapshot_slot_prefix(&registration.device_id.to_string(), next_sequence)
                    )
            {
                return Err(DbError::Message(
                    "Store snapshot successor is outside its activated exact stream".to_string(),
                ));
            }
            for blob in &blobs {
                validate_snapshot_blob_plan_on(conn, &gates, &synced_tables, &meta, blob)?;
            }
            tx.execute(
                "INSERT INTO outbound_store_snapshot \
                 (singleton, snapshot_ref, meta_prepared, image_ref, image_prepared, \
                  image_bytes, meta_bytes, blobs) \
                 VALUES (1, ?1, ?2, ?3, ?4, ?5, ?6, ?7)",
                rusqlite::params![
                    serde_json::to_string(&reference).map_err(|error| DbError::Message(
                        format!("serialize exact Store snapshot ref: {error}")
                    ))?,
                    serde_json::to_string(&meta_prepared).map_err(|error| DbError::Message(
                        format!("serialize prepared Store snapshot metadata: {error}")
                    ))?,
                    serde_json::to_string(&meta.image).map_err(|error| DbError::Message(
                        format!("serialize exact Store snapshot image ref: {error}")
                    ))?,
                    serde_json::to_string(&image_prepared).map_err(|error| DbError::Message(
                        format!("serialize prepared Store snapshot image: {error}")
                    ))?,
                    image_bytes,
                    meta.to_bytes(),
                    serde_json::to_string(&blobs).map_err(|error| DbError::Message(format!(
                        "serialize prepared Store snapshot blobs: {error}"
                    )))?,
                ],
            )
            .map_err(DbError::from)?;
            tx.commit().map_err(DbError::from)?;
            Ok(reference)
        })
        .await
    }

    pub(crate) async fn latest_local_store_snapshot(
        &self,
    ) -> Result<Option<PublishedStoreSnapshot>, DbError> {
        self.call(load_published_store_snapshot_on).await
    }

    pub(crate) async fn complete_snapshot_publication(
        &self,
        accepted: StoreSnapshotRef,
    ) -> Result<(), DbError> {
        self.call(move |conn| {
            let tx = conn.unchecked_transaction().map_err(DbError::from)?;
            let outbound = load_outbound_store_snapshot_on(&tx)?
                .ok_or_else(|| DbError::Message("outbound Store snapshot is absent".to_string()))?;
            if outbound.reference != accepted {
                return Err(DbError::Message(
                    "accepted Store snapshot differs from the prepared exact object".to_string(),
                ));
            }
            for blob in &outbound.blobs {
                install_snapshot_blob_plan_on(&tx, blob)?;
                if let Some(path) = &blob.spool_path {
                    tx.execute(
                        "INSERT INTO snapshot_blob_spool_cleanup (path) VALUES (?1)
                         ON CONFLICT(path) DO NOTHING",
                        [path.to_string_lossy().as_ref()],
                    )
                    .map_err(DbError::from)?;
                }
            }
            let deleted = tx
                .execute(
                    "DELETE FROM outbound_store_snapshot \
                     WHERE singleton = 1 AND snapshot_ref = ?1",
                    [serde_json::to_string(&accepted).map_err(|error| {
                        DbError::Message(format!("serialize accepted Store snapshot ref: {error}"))
                    })?],
                )
                .map_err(DbError::from)?;
            if deleted != 1 {
                return Err(DbError::Message(
                    "outbound snapshot ownership row is absent or changed".to_string(),
                ));
            }
            tx.execute(
                "INSERT INTO published_store_snapshot \
                 (singleton, snapshot_ref, successor_slot, meta_bytes) VALUES (1, ?1, ?2, ?3) \
                 ON CONFLICT(singleton) DO UPDATE SET \
                   snapshot_ref = excluded.snapshot_ref, \
                   successor_slot = excluded.successor_slot, \
                   meta_bytes = excluded.meta_bytes",
                rusqlite::params![
                    serde_json::to_string(&accepted).map_err(|error| DbError::Message(format!(
                        "serialize published Store snapshot ref: {error}"
                    )))?,
                    serde_json::to_string(&outbound.meta.value.successor.next_slot).map_err(
                        |error| DbError::Message(format!(
                            "serialize Store snapshot successor slot: {error}"
                        ))
                    )?,
                    outbound.meta.bytes,
                ],
            )
            .map_err(DbError::from)?;
            tx.commit().map_err(DbError::from)
        })
        .await
    }

    pub(crate) async fn snapshot_blob_spool_cleanup_paths(&self) -> Result<Vec<PathBuf>, DbError> {
        self.call(|conn| {
            let mut statement = conn
                .prepare("SELECT path FROM snapshot_blob_spool_cleanup ORDER BY path")
                .map_err(DbError::from)?;
            let paths = statement
                .query_map([], |row| row.get::<_, String>(0))
                .map_err(DbError::from)?
                .map(|row| row.map(PathBuf::from).map_err(DbError::from))
                .collect();
            paths
        })
        .await
    }

    pub(crate) async fn complete_snapshot_blob_spool_cleanup(
        &self,
        path: &Path,
    ) -> Result<(), DbError> {
        let path = path.to_string_lossy().into_owned();
        self.call(move |conn| {
            let deleted = conn
                .execute(
                    "DELETE FROM snapshot_blob_spool_cleanup WHERE path = ?1",
                    [&path],
                )
                .map_err(DbError::from)?;
            if deleted != 1 {
                return Err(DbError::Message(
                    "snapshot blob spool cleanup ownership is absent".to_string(),
                ));
            }
            Ok(())
        })
        .await
    }

